import{_ as o,o as d,c as t,a3 as c}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"网页控制台：选择模型、key 和订阅套餐","description":"","frontmatter":{},"headers":[],"relativePath":"zh/web.md","filePath":"zh/web.md"}'),s={name:"zh/web.md"};function a(n,e,i,r,p,l){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="网页控制台-你的模型、你的-key、你的套餐" tabindex="-1">网页控制台：选择模型、key 和订阅套餐 <a class="header-anchor" href="#网页控制台-你的模型、你的-key、你的套餐" aria-label="Permalink to &quot;网页控制台：选择模型、key 和订阅套餐 {#网页控制台-你的模型、你的-key、你的套餐}&quot;">​</a></h1><p>登录、退出登录或切换模型后，控制台会重新获取服务商目录。缓存失效前发出的请求不能再写回缓存，后续读取也不会复用旧请求。</p><p>刷新记忆时，最新列表和近期修改会一并保留。即使较早的请求较晚返回，也不会让已经删除的记忆重新出现。刷新失败会保留上次加载的内容；离开页面后，不再显示尚未返回的刷新错误。</p><p>技能列表同样只采用最新一次完成的刷新结果。重新加载失败时保留当前列表，离开页面后丢弃未处理的错误提示。</p><p>聊天的 <code>/</code> 菜单在刷新失败时保留已加载的技能，并忽略旧响应。关闭技能后，菜单中的相关建议和键盘补全会立即隐藏。</p><p>「每日」、首次设置清单和形象工作室都会忽略旧刷新结果，以及离开页面后才返回的错误。工作室刷新时会保留你填写的描述和当前选择；切换到另一轮绘图任务时，则会清除候选图选择，要求重新确认。</p><blockquote><p>网页控制台是 <code>nanomuse serve</code> 在 <code>/</code> 提供的网页，用于操作自行部署的运行时。早期桌面版也使用这个界面；当前<a href="./desktop">桌面版</a>使用 DeepSeek Harness。运行时是执行智能体与工具的后台程序，详见 <a href="./app">app.md</a>。本页说明控制台如何选择回答模型，以及缺少某种模型能力时如何引导配置。创建 key（访问模型服务的密钥）见 <a href="./own-key">own-key.md</a>。</p></blockquote><h2 id="one-catalogue" tabindex="-1">共用的服务商目录 <a class="header-anchor" href="#one-catalogue" aria-label="Permalink to &quot;共用的服务商目录 {#one-catalogue}&quot;">​</a></h2><p>控制台、手机、桌面版和中继共用 <a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/llm/providers.json" target="_blank" rel="noreferrer"><code>nanomuse/llm/providers.json</code></a> 中的服务商目录，遵循约定 C11。中继是负责账号和设备间通信的服务器。目录列出各服务商 key 支持的能力：<code>chat</code> 用于对话，<code>vision</code> 用于让「手」看懂截图，<code>image</code> 用于形象工作室绘图，<code>video</code> 用于生成短视频；也列出 key 以外的登录方式。</p><p>控制台优先调用运行时的 <code>GET /api/providers</code>，同时获知当前配置的模型位置及其能力。连接不支持该接口的旧版运行时时，改用构建时打包的目录副本，但无法据此得知当前配置。实现位于 <code>web/src/providers.ts</code>，排序、映射和提示语由 <code>web/src/providers.test.ts</code> 检查。</p><h2 id="where-it-shows" tabindex="-1">各处如何选择模型 <a class="header-anchor" href="#where-it-shows" aria-label="Permalink to &quot;各处如何选择模型 {#where-it-shows}&quot;">​</a></h2><p><strong>连接 → 对话模型</strong>。 服务商卡片来自运行时预设，当前地区的推荐项排在最前：中国大陆为阿里云百炼，其他地区为 OpenRouter，逻辑见 <a href="https://github.com/nano-muse/nanoMuse/blob/main/web/src/region.ts" target="_blank" rel="noreferrer">region.ts</a>。选中卡片后，下方会说明该 key 支持的能力和使用限制，包括 Kimi 各版本差异、OpenRouter Image API，以及 ChatGPT 的使用注意事项。API 是程序调用服务的接口。</p><p>「动手模型」列出能看图的模型，用于读取屏幕截图。默认选择该服务商目录中的 <code>defaults.hands</code>；如果它没有视觉模型，但你已登录账号，则使用账号的动手模型。如果服务商不支持 <code>vision</code>，而你也没有登录，页面只显示缺少视觉模型的说明，不会选一个无法看图的模型来操作屏幕。下方「代理（可选）」接受 <code>http://host:port</code>、<code>https://</code> 或 <code>socks5://</code> 地址，只代理该服务商的请求，对应 <code>[llm] proxy</code>。nanoMuse Cloud 不经过此代理，使用 SOCKS 需要运行时安装 <code>httpx[socks]</code>。保存过的密码显示为圆点，清空字段即可删除。</p><p><strong>连接 → 对话模型 → 你自己的接口</strong>。 支持 OpenAI API、但未列入目录的服务可以保存为自定义端点，也就是一个模型服务地址，例如网关、中转服务、其他电脑上的 vLLM 或 LM Studio。运行时允许保存多个端点，见 #294。「本地或你自己的端点」下，每个已保存端点各有一张卡片，显示名称和主机名。最后的「添加接口」可填写名称（可选，默认使用主机名）、Base URL（接口基础地址）、API key 或「无需密钥」。如果服务无法通过 <code>/models</code> 列出模型，表单会提示手填模型 id。</p><p>每个端点的 key 分别存入保险库，名称为 <code>ENDPOINT_&lt;ID&gt;_API_KEY</code>，添加新端点不会更改已有端点的 key。选中卡片后，下方会显示 key 的存储位置、模型数量和正在使用它的模型位置，并提供「改名」「换密钥」「编辑模型」「重新获取模型」「移除」。对话选择器会列出该端点的模型。「保存」通过端点 id 设置对话模型，即 <code>PUT /api/connections/llm {&quot;endpoint&quot;: &quot;&lt;id&gt;&quot;, &quot;model&quot;: ...}</code>，无需重新填写地址或 key。修改端点名称、key 或地址，会同时影响所有引用它的模型位置。</p><p>「动手模型」也会为列表中的其他端点各显示一组模型。选中后，屏幕截图通过该端点发送，并使用其 key，接口为 <code>PUT /api/connections/gui {&quot;endpoint&quot;: &quot;&lt;id&gt;&quot;, &quot;model&quot;: ...}</code>。「生成图片」和「生成视频」同样在「你的接口」下列出这些端点，调用 <code>PUT /api/connections/image</code> / <code>/video</code>，传入 <code>endpoint</code> 和 <code>model</code>。</p><p>正在承担对话的端点不能删除，需要先切换对话模型。删除端点后，引用它的动手、图片和视频模型恢复「自动」，对应 key 也从保险库删除。端点列表功能出现之前，配置为「其他 OpenAI 兼容接口」的对话服务，会在运行时下次启动时自动迁移为第一个端点，并将 key 复制到该端点的保险库条目中。原条目通常是 <code>LLM_API_KEY</code>，由于 <code>config.toml</code> 可能仍在引用它，程序会保留。确认不再引用后，可用 <code>DELETE /api/vault/{name}</code> 手动删除。</p><p>同一地址只能保存一个端点。添加或修改时若与其他端点地址重复，程序会拒绝，并指出已有端点。<code>GET /api/connections</code> 的 <code>endpoints</code> 返回列表，每项为 <code>{id, label, base_url, key_source, models, slots}</code>，不包含 key。路由见 <a href="./app#api">app.md</a>。不支持端点列表的运行时仍显示原来的单张「其他 OpenAI 兼容接口」卡片。</p><p><strong>连接 → 生成图片、生成视频</strong>。 这是模型约定在 0.1.41 增加的两个媒体模型位置，分别以卡片显示在对话模型下方。卡片显示运行时实际解析出的「服务商 · 模型」，来自 <code>GET /api/connections</code> 的 <code>image</code> / <code>video</code> 及 <code>effective_*</code> 字段。选择顺序为：你明确指定的模型；否则使用对话服务商提供的对应媒体模型；否则使用你配置的第一个支持该任务的服务商。均不可用时，显示说明和「添加服务商」。项目托管的 nanoMuse Cloud 不提供媒体生成。</p><p>选择器首先提供「自动」。如果对话服务商支持该能力，还会提供「对话模型的服务商」，直接沿用它的 key。「添加服务商」列出当前地区目录内具备该能力的服务商，也提供可填 Base URL 的「其他 OpenAI 兼容接口」；不具备该能力的服务商不会出现。模型可从端点返回的列表中选择，也可使用目录默认值。</p><p>「保存」调用 <code>PUT /api/connections/image</code> 或 <code>/video</code>，参数包括 <code>provider</code>（目录 id，或带 <code>base_url</code> 的 <code>openai</code>）、<code>model</code>、<code>base_url</code>、<code>api_key</code>。key 存为 <code>IMAGE_API_KEY</code> / <code>VIDEO_API_KEY</code>；选择对话服务商时沿用对话 key。「自动」会将四项全部置空，清除显式配置。动手、图片和视频三个从属位置都遵循同一规则：选择器首项是「自动」，保存后重新按默认顺序解析。动手模型对应 <code>PUT /api/connections/gui {&quot;model&quot;: &quot;&quot;}</code>。控件下方的「当前为 服务商 · 模型」根据 <code>effective_*</code> 显示实际结果。旧版运行时没有这些路由时，不显示媒体卡片。实现见 <code>web/src/models.ts</code>，测试见 <code>web/src/models.test.ts</code>。</p><p>「动手模型」「图片模型」「短片模型」共用 <code>web/src/components/ModelPicker.tsx</code>。点击显示「服务商 · 模型」的按钮后打开面板，「自动」排第一。OpenRouter、硅基流动等服务商模型较多，默认只显示八个，其中该位置的目录默认模型和当前模型优先；组末可点「还有 {n} 个」。总行数超过八行时出现「搜索模型」，按模型 id 或名称实时筛选所有组，无结果时显示「没有匹配的模型」。按 Esc 或点击面板外关闭。折叠与搜索逻辑在 <code>web/src/model-list.ts</code>，由 <code>web/src/model-list.test.ts</code> 检查。</p><p><strong>连接 → 或者用 ChatGPT 套餐登录</strong>。 卡片调用 <code>POST /api/chatgpt/login</code> 获取 <code>{url}</code>，在新标签页打开 Codex 登录页。随后每两秒查询 <code>GET /api/chatgpt/status</code>，最多十分钟。登录令牌存入运行时后，卡片提供「让它来回答对话」，对应 <code>[llm] provider = &quot;chatgpt&quot;</code>，以及「退出 ChatGPT」，对应 <code>POST /api/chatgpt/logout</code>。卡片会说明套餐支持对话和屏幕操作、不支持图片和视频生成，并提示 OpenAI 条款方面的限制。旧版运行时若返回 404，页面会改为提示终端命令 <code>nanomuse chatgpt login</code>。</p><p>登录回调会访问运行时所在电脑的 1455 端口。如果运行时在别的电脑上，或该端口被占用，浏览器最终可能停在打不开的地址。端口未成功绑定时，登录响应包含 <code>port_bound: false</code>。卡片始终提供一个地址输入框，可将浏览器最终地址交回运行时，调用 <code>POST /api/chatgpt/callback {url}</code>；链接状态不符返回 400 <code>state_mismatch</code>，登录开始已超过十分钟则返回 409 <code>no_login</code>。端口无法绑定时，输入框旁还会说明原因。详见 <a href="./configuration#a-chatgpt-plan-instead-of-a-key">configuration.md</a>。</p><p><strong>额度卡片</strong>。 「账号」页以及聊天收到 <code>allowance_exhausted</code> 时都会显示三种继续方式。第一种是「换成自己的 key」：显示本地区优先推荐的服务商、「设置一下」（打开「连接」并选中该服务商）、「到 … 获取密钥」和配置指南。「其他服务商，以及各自的 key 能做什么」下还列出地区列表中的其余服务商，各自附能力说明、设置按钮和 key 链接。中继 0.21 起若返回 <code>guidance.providers</code> 就使用该列表，否则使用本地目录。第二种是「用你已经在付费的套餐登录」，卡片内直接提供 ChatGPT 登录。第三种是邀请。已用 80 % 的提醒和首次登录面板也指向这些选项。</p><p><strong>形象工作室</strong>。 未配置图像模型时，「画」按钮不可用，下方说明缺少的能力。中国大陆会列出「阿里云百炼、智谱 GLM、硅基流动或火山方舟」，其他地区为「OpenRouter、OpenAI、Google Gemini 或 xAI Grok」，旁边提供「更换」。运行时报告图片或视频生成不可用时，设置 → 图像与视频模型 也会显示相同说明。</p><h2 id="the-first-run-and-the-chat-s-opening" tabindex="-1">首次设置与聊天开场 <a class="header-anchor" href="#the-first-run-and-the-chat-s-opening" aria-label="Permalink to &quot;首次设置与聊天开场 {#the-first-run-and-the-chat-s-opening}&quot;">​</a></h2><p>首次设置按「接一个模型 → 连接邮箱、日历、联系人（可选）→ 开始」进行，没有单独的起名页。「开始」调用 <code>POST /api/firstrun/start {lang}</code>，标记首次设置完成并打开第一次聊天。开场与手机、桌面版一致，遵循 <a href="./parity">parity.md</a> 中的约定 C4：</p><ol><li><strong>App 先显示三句话</strong>。 它以智能体身份、用控制台当前语言打招呼，介绍如何在这台电脑上工作，包括读取你指定的文件、操作前询问和消息发送去向，再问如何称呼你。这三句不消耗 token（模型输入输出的计量单位），也不会作为消息发给模型，只显示在历史开头。<code>GET /api/firstrun?lang=</code> 的 <code>intro</code> 返回这些文字。</li><li><strong>模型询问你的称呼</strong>。 你回答或拒绝后，模型在回复末尾的 <code>```nanomuse-naming</code> 块中报告结果，使用桌面版和手机共用的 JSON 字段 <code>user_address</code>、<code>suggest</code>、<code>agent_name</code>，解析位于 <code>nanomuse/fences.py</code>。运行时管理 <code>none → ask_user_name → ask_agent_name → named → done</code> 阶段，代码为 <code>nanomuse/server/firstrun.py</code>，状态存入资料旁的 <code>firstrun.json</code>。你的称呼会写入资料和记忆中的 <code>Call them: …</code>，并通过 socket 的 <code>firstrun</code> 消息通知页面。socket 是保持实时通信的连接。命名代码块不会显示，即使尚未接收完整也不会露出。</li><li><strong>回复下方显示起名选项</strong>。 卡片列出模型建议的两三个名字；模型没有建议时，从内置名单取两个，再提供「换一个」供你自定。点选名字会立即通过 <code>POST /api/firstrun/pick {name}</code> 保存，并把它作为你的消息发送，让模型接着以该名字回答。1.0.8 起，「换一个」直接在卡片内打开输入框，输入后的处理与点选一致；即使模型没有在代码块中重复名字，卡片也会关闭。如果在聊天输入框里起名，则仍由模型收到，再通过命名块返回。形象选项等由 App 自行处理的卡片会调用 <code>POST /api/firstrun/dismiss</code>，关闭起名卡片。</li></ol><p>首次对话中的轮次不会计入请求用户点 Star 所依据的任务数。说明开场流程的附加提示，只发送到绑定的首次聊天，不会进入例程、动态任务或其他聊天。「跳过设置」只标记为已完成引导，不启动这段对话。之后仍可在设置中的身份表单修改名字、形象和语气。不支持这些路由的旧版运行时，继续显示原有问候及不含表单的设置清单。</p><h2 id="the-sentences" tabindex="-1">错误与权限提示 <a class="header-anchor" href="#the-sentences" aria-label="Permalink to &quot;错误与权限提示 {#the-sentences}&quot;">​</a></h2><p>功能不可用时，控制台用一句具体说明代替原始错误。<code>unavailableLine(cap, region, locale)</code> 会从地区目录中取最多四家具备该能力的服务商，按目录顺序生成提示：</p><table tabindex="0"><thead><tr><th>能力</th><th>English</th><th>中文</th></tr></thead><tbody><tr><td><code>image</code></td><td>Pictures need a provider with image models: {providers}.</td><td>画图需要一个有图像模型的服务商：{providers}。</td></tr><tr><td><code>video</code></td><td>Clips need a provider with video models: {providers}.</td><td>生成视频需要一个有视频模型的服务商：{providers}。</td></tr><tr><td><code>vision</code></td><td>The hands need a model that sees pictures: {providers}.</td><td>动手需要一个能看图的模型：{providers}。</td></tr><tr><td><code>chat</code></td><td>Chat needs a model: {providers}.</td><td>对话需要一个模型：{providers}。</td></tr></tbody></table><p>每句旁边的「怎么做」链接指向 <a href="./own-key">own-key.md</a>。服务商名称按控制台语言，从目录的 <code>name</code> / <code>name_zh</code> 取得。</p><p><strong>中继拒绝请求时</strong>，控制台根据 <code>code</code> 显示对应说明。说明定义于 <code>nanomuse/server/failures.py</code>，英文句子也是 <code>web/src/i18n/zh-CN.ts</code> 中查找中文的键。情况包括额度耗尽（附继续使用的选项卡片）、达到每日上限、限流、key 无效、账号停用、中继不支持该模型、上游服务商故障。0.1.40 起还区分了原先统一显示为「模型服务商返回了一个错误：…」的四类错误，以及运营者开关触发的五类状态，见 <a href="./cloud#controls">cloud.md</a>：</p><table tabindex="0"><thead><tr><th>中继说</th><th>聊天里显示</th></tr></thead><tbody><tr><td><code>413 too_large</code></td><td>这条消息超出了模型的上下文窗口。精简一下、去掉部分附件，或者开一个新对话。</td></tr><tr><td><code>403 not_invited</code></td><td>这个中继只接受邀请注册；在「账号」里用邀请码登录。</td></tr><tr><td><code>429 too_many_in_flight</code></td><td>这个账号同时进行的对话太多了，等一轮结束后再试。</td></tr><tr><td><code>429 provider_busy</code></td><td>模型服务商正忙，稍后再试。</td></tr><tr><td><code>429 allowance_exhausted</code> 且 <code>paused: true</code></td><td>这个中继暂时停发了免费额度，不是用完了。在「连接」里填上你自己的模型 key 就能继续；你的登录、设备和剩余额度都保持原样。（显示与额度耗尽相同的继续选项卡片，通知包含 <code>paused</code>）</td></tr><tr><td><code>403 signup_closed</code></td><td>这个中继暂时停止了新注册，已有账号照常使用。稍后再试。</td></tr><tr><td><code>503 service_paused</code></td><td>nanoMuse Cloud 被运营者暂时停用了，你的登录和数据都保留着。稍后再试。</td></tr><tr><td><code>503 sync_paused</code></td><td>这个中继暂时停止了对话同步，已存的内容保留着，各设备各自继续使用。</td></tr><tr><td><code>503 hub_paused</code></td><td>这个中继暂时停止了设备互联，各设备各自继续使用。</td></tr></tbody></table><p>原始响应保留在「详情」中，供报告问题时使用，不会只显示原始内容。</p><p><strong>自己的模型请求失败时</strong>，例如 key 被拒、模型不存在、限流、超时或连接失败，页面会说明原因。如果你已登录，且当前聊天不用账号模型，还会出现「这次改用 nanoMuse Cloud」，与桌面版、手机的 own-key 模型约定第 4 节一致。该按钮将相同消息带上 <code>via: &quot;cloud&quot;</code> 重新发送，通过 <code>POST /api/threads/{id}/send</code> 或 socket 的 <code>send</code> 消息提交。运行时只将这轮交给中继推荐的对话模型，使用账号 key；下一轮仍回到你自己的模型。</p><p>此操作不修改 <code>[llm]</code>、「使用 nanoMuse Cloud 模型」开关或当前对话配置。关闭 Cloud 模型后，只有主动点击此按钮才会消耗额度。用户消息、回复和该轮失败提示都会携带 <code>model_used</code> 模型 id；回复下方显示「这次由 nanoMuse Cloud 回答（模型）」。已含 <code>model_used</code> 的失败提示不再重复提供重试按钮。未登录时返回 <code>401 signed_out</code>，按钮下显示「请先登录 nanoMuse Cloud。」当前聊天仍使用账号模型时关闭 Cloud，会返回 <code>409 chat_on_cloud</code>，开关下显示「先添加一个自己的服务商；关掉 nanoMuse Cloud 后没有别的模型能回答。」</p><p><strong>连接测试失败时</strong>，模型或动手设置中的「测试」会显示与聊天相同的错误说明。<code>POST /api/connections/llm/test</code> 返回 <code>{ok: false, code, error, detail}</code>，其中 <code>error</code> 是易读说明，<code>detail</code> 是服务商原文，显示在「详情」中。</p><p><strong>哨兵为何请求确认</strong>，由运行时依据设置说明。哨兵（Sentinel）是执行前检查操作风险和授权的组件。原因可能是 <code>&#39;shell&#39; is in always_ask_tools</code>、<code>risk level is &#39;sensitive&#39; (mode=ask)</code>、<code>covered by your &#39;always&#39; permission for shell:ls</code>，或数据污染检查。<code>web/src/i18n/index.ts</code> 的 <code>localReason()</code> 识别这些格式，按控制台语言转换为句子，并保留工具名、风险和目标地址。今日记录中被拒绝的步骤也显示同样说明；不识别的格式则保留原文。</p><p><strong>已授予的权限</strong>，可从头像 → 权限 查看。列表按工具风险从高到低排列：敏感、中等、安全，分类取自 <code>GET /api/state</code> 的 <code>settings.tools</code>。每条列出工具、授权有效期和授予时间，均可单独撤销。</p><h2 id="checks" tabindex="-1">检查 <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;检查 {#checks}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; LANG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">en_US.UTF-8</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>构建产物写入 <code>nanomuse/server/static/</code>，应随修改一同提交；<code>web/tsconfig.tsbuildinfo</code> 是构建过程的副产物，不提交。</p>',45)])])}const k=o(s,[["render",a]]);export{u as __pageData,k as default};
